const $=id=>document.getElementById(id);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const product=r=>r.tags.map(t=>({met:'Metallurgical',thermal:'Thermal',unknown:'Not classified'})[t]).join(' + ');
export async function initIndustry({data,select,focusFeature,pause}){
  const response=await fetch('./data/industry.json');if(!response.ok)throw Error('Industry inventory unavailable');const industry=await response.json();
  let selected=null,filtered=industry.records;
  const regions=[...new Set(industry.records.map(r=>r.region))].sort();
  document.querySelector('footer').insertAdjacentHTML('beforebegin',`<section id="industryPanel" hidden aria-label="NSW coal industry inventory"><div class="industry-head"><div><span class="eyebrow">GEOLOGY CONNECTED TO INDUSTRY</span><h2>Coal across New South Wales</h2><p>${esc(industry.coverageNote)}</p></div><button id="backGeology">← Geology</button></div><div class="industry-filters"><label class="sr-only" for="mineSearch">Search mines, operators and regions</label><input id="mineSearch" type="search" placeholder="Search mine, operator or region…"><label class="sr-only" for="mineRegion">Coalfield region</label><select id="mineRegion"><option value="all">All regions</option>${regions.map(r=>`<option>${r}</option>`).join('')}</select><label class="sr-only" for="mineProduct">Coal use</label><select id="mineProduct"><option value="all">All coal uses</option><option value="thermal">Thermal</option><option value="met">Metallurgical</option><option value="unknown">Not classified</option></select><button id="exportMines">Export CSV</button></div><p id="industryCount" class="industry-stat" aria-live="polite"></p><div class="industry-layout"><div><div id="industryMap"></div><div class="industry-table-wrap"><table class="industry-table"><thead><tr><th>Mine / operation</th><th>Region</th><th>Operator / group</th><th>Coal use</th><th>3D coverage</th></tr></thead><tbody id="mineRows"></tbody></table></div></div><article id="industryDetail"><span class="eyebrow">EXPLORE AN OPERATION</span><h3>Choose a mine</h3><p>Compare its geology, operator, products and documented destinations. Missing information is shown explicitly.</p><p class="micro">Production is reported at complex level where applicable. Do not add a complex total once for every component mine.</p></article></div></section>`);
  function open(value=true){pause();document.body.classList.toggle('industry-open',value);$('industryPanel').hidden=!value;$('industryToggle').setAttribute('aria-pressed',String(value));if(value)render();}
  function render(){
    const query=$('mineSearch').value.trim().toLowerCase(),region=$('mineRegion').value,tag=$('mineProduct').value;
    filtered=industry.records.filter(r=>(region==='all'||r.region===region)&&(tag==='all'||r.tags.includes(tag))&&[r.name,r.registryName,r.operator,r.region].join(' ').toLowerCase().includes(query));
    $('industryCount').textContent=`${filtered.length} of ${industry.records.length} registry records · source snapshot ${industry.date}`;
    $('mineRows').innerHTML=filtered.length?filtered.map(r=>`<tr class="${selected===r.id?'selected':''}"><td><button data-mine="${r.id}">${esc(r.name)}</button></td><td>${esc(r.region)}</td><td>${esc(r.operator??'Not verified')}</td><td>${product(r)}</td><td>${r.in3D?'Regional model':'Inventory only'}</td></tr>`).join(''):'<tr><td colspan="5">No mines match. Clear the search or choose a different filter.</td></tr>';
    $('mineRows').querySelectorAll('[data-mine]').forEach(el=>el.onclick=()=>show(el.dataset.mine));
    const X=x=>45+(x-149.65)/2.35*870,Y=y=>24+(-30.35-y)/4.4*226;
    let map='<rect width="960" height="280" fill="#102530"/>';
    for(const lat of [-31,-32,-33,-34])map+=`<path d="M45 ${Y(lat)}H930" stroke="#294450" stroke-dasharray="3 4"/><text x="8" y="${Y(lat)+3}" fill="#829fac" font-size="10">${Math.abs(lat)}°S</text>`;
    for(const lon of [150,151,152])map+=`<path d="M${X(lon)} 20V252" stroke="#294450" stroke-dasharray="3 4"/><text x="${X(lon)}" y="271" fill="#829fac" font-size="10">${lon}°E</text>`;
    for(const r of filtered){const color=r.tags.includes('met')?'#f7b967':r.tags.includes('thermal')?'#58d8de':'#9da8c7';map+=`<g data-id="${r.id}" role="button" tabindex="0" aria-label="${esc(r.name)}"><title>${esc(r.name)}</title><circle cx="${X(r.lon)}" cy="${Y(r.lat)}" r="9" fill="transparent"/><circle cx="${X(r.lon)}" cy="${Y(r.lat)}" r="${selected===r.id?6:3.5}" fill="${color}" stroke="${selected===r.id?'white':'#102530'}" stroke-width="1.5"/></g>`;}
    map+='<text x="690" y="30" fill="#9ab4c1" font-size="11">NSW mine locations · coordinate overview</text>';
    $('industryMap').innerHTML=`<svg viewBox="0 0 960 280" role="img" aria-label="Geographic distribution of filtered NSW mines">${map}</svg>`;
    $('industryMap').querySelectorAll('[data-id]').forEach(el=>{el.onclick=()=>show(el.dataset.id);el.onkeydown=e=>{if(e.key==='Enter')show(el.dataset.id);};});
  }
  function show(id){
    const r=industry.records.find(r=>r.id===id);if(!r)return;selected=id;render();
    const routes=industry.routes.filter(l=>l.fromId===id),complex=industry.complexes[r.complexId];
    const sourceIds=[...new Set([...r.sources,...(complex?[complex.source]:[]),...routes.flatMap(r=>r.sources)])];
    const sourceLinks=sourceIds.map(id=>industry.sources.find(s=>s.id===id)).filter(Boolean).map(s=>`<li><a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title)}</a></li>`).join('');
    $('industryDetail').innerHTML=`<span class="eyebrow">${esc(r.region)} COALFIELD</span><h3>${esc(r.name)}</h3><p>${esc(r.description)}</p><dl><dt>Operator / group</dt><dd>${esc(r.operator??'Not verified')}</dd><dt>Coal use</dt><dd>${product(r)}</dd><dt>Method</dt><dd>${esc(r.method??'Not recorded')}</dd><dt>Registry status</dt><dd>${esc(r.registryStatus)}</dd></dl><p class="source-date">${esc(r.statusNote)} Snapshot ${industry.date}.</p><h4>Ownership</h4><p>${esc(r.ownership??'Ownership stakes have not yet been verified. Operator identity is not an ownership statement.')}</p>${complex?`<h4>${esc(complex.name)} · ${complex.period}</h4><p><strong>${complex.saleableMt} Mt saleable coal</strong>${complex.romMt!==null?` · ${complex.romMt} Mt run-of-mine`:''}</p><p class="source-date">${esc(complex.basis)}. This is a complex total, not an individual-mine allocation.</p>`:'<h4>Production</h4><p>Comparable actual production has not yet been populated.</p>'}${r.capacity?`<h4>Approved capacity</h4><p>${r.capacity.value} ${r.capacity.unit} · ${esc(r.capacity.basis)}</p>`:''}<h4>Geology</h4><p>${r.seams.length?r.seams.map(id=>esc(data.seams.find(s=>s.id===id)?.name??id)).join(', '):'No individual seam surface is linked in this atlas.'}</p><h4>Documented destinations</h4>${routes.length?routes.map(l=>`<p>↗ ${esc(industry.destinations.find(d=>d.id===l.toId)?.name)}<br><span class="source-date">${esc(l.mode)} · schematic relationship</span></p>`).join(''):'<p>No destination relationship has yet been verified in the atlas. This does not mean the mine has no customers.</p>'}${r.in3D?'<button id="viewMine3D" class="primary">Explore in 3D ↗</button>':'<p class="source-date">Outside the current detailed 3D coverage.</p>'}<details><summary>Sources & provenance</summary><p class="source-date">GSNSW record ${r.registryId}. Operator evidence reviewed ${r.reviewedAt}.</p><ul>${sourceLinks}</ul></details>`;
    if($('viewMine3D'))$('viewMine3D').onclick=()=>{open(false);select(id);focusFeature(id);};
  }
  $('industryToggle').onclick=()=>open($('industryPanel').hidden);$('backGeology').onclick=()=>open(false);
  for(const id of ['mineSearch','mineRegion','mineProduct'])$(id).addEventListener('input',render);
  $('exportMines').onclick=()=>{
    const csvCell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';
    const rows=[['Mine','Region','Operator / group','Coal use','Registry status','Snapshot','Longitude','Latitude','Complex ID','Source URLs'],...filtered.map(r=>[r.name,r.region,r.operator,product(r),r.registryStatus,industry.date,r.lon,r.lat,r.complexId,r.sources.map(id=>industry.sources.find(s=>s.id===id)?.url).filter(Boolean).join(' | ')])];
    const url=URL.createObjectURL(new Blob(['\uFEFF'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='NSW-coal-industry.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
  };
  window.coalIndustry={getState:()=>({total:industry.records.length,filtered:filtered.map(r=>r.id),selected,open:!$('industryPanel').hidden})};
  return {open};
}
